// Declarações de módulo para assets (Metro/Expo devolve um asset id numérico).
declare module "*.png" {
  const value: number;
  export default value;
}
declare module "*.jpg" {
  const value: number;
  export default value;
}
declare module "*.jpeg" {
  const value: number;
  export default value;
}
declare module "*.gif" {
  const value: number;
  export default value;
}
declare module "*.webp" {
  const value: number;
  export default value;
}
